<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class StudentMovementController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head')||$r->user()->canDo('students.manage'),403);}
 public function create(Request $r,$student){$this->ok($r);$s=DB::table('students')->find($student);abort_if(!$s,404);return view('academic-office.movement',['s'=>$s,'groups'=>DB::table('study_groups')->where('active',1)->orderBy('name')->get()]);}
 public function store(Request $r,$student){$this->ok($r);$p=$r->attributes->get('academic_period');$s=DB::table('students')->find($student);abort_if(!$s,404);PeriodGuard::writable($p->id);$d=$r->validate(['type'=>'required|in:enrollment,transfer,academic_leave,return_from_leave,expulsion,graduation,reinstatement','to_group_id'=>'nullable|exists:study_groups,id','effective_on'=>'required|date','order_number'=>'required|string|max:100','order_date'=>'required|date','basis'=>'nullable|string|max:5000']);if(in_array($d['type'],['enrollment','transfer','return_from_leave','reinstatement']))abort_unless($d['to_group_id'],422,'Нужно выбрать группу.');DB::transaction(function()use($r,$p,$s,$d){DB::table('student_movements')->insert(array_merge($d,['student_id'=>$s->id,'academic_period_id'=>$p->id,'from_group_id'=>$s->current_group_id,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]));$status=match($d['type']){'academic_leave'=>'academic_leave','expulsion'=>'expelled','graduation'=>'graduated',default=>'active'};$group=in_array($d['type'],['enrollment','transfer','return_from_leave','reinstatement'])?$d['to_group_id']:$s->current_group_id;DB::table('students')->where('id',$s->id)->update(['current_group_id'=>$group,'status'=>$status,'left_on'=>in_array($status,['expelled','graduated'])?$d['effective_on']:null,'updated_at'=>now()]);if($group&&$status==='active')DB::table('student_group_memberships')->updateOrInsert(['student_id'=>$s->id,'academic_period_id'=>$p->id],['study_group_id'=>$group,'starts_on'=>$d['effective_on'],'ends_on'=>null,'status'=>'active','created_at'=>now(),'updated_at'=>now()]);DB::table('student_orders')->updateOrInsert(['number'=>$d['order_number'],'order_date'=>$d['order_date']],['academic_period_id'=>$p->id,'student_id'=>$s->id,'type'=>$d['type'],'title'=>'Движение контингента: '.$d['type'],'basis'=>$d['basis']??null,'status'=>'registered','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);});return redirect()->route('student.record',$s->id)->with('success','Движение зарегистрировано.');}
 public function plan(Request $r,$student){$this->ok($r);$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);$d=$r->validate(['subject_id'=>'required|exists:subjects,id','planned_hours'=>'nullable|integer|min:0|max:9999','control_type'=>'nullable|string|max:100','note'=>'nullable|string|max:5000']);DB::table('individual_study_plans')->updateOrInsert(['academic_period_id'=>$p->id,'student_id'=>$student,'subject_id'=>$d['subject_id']],array_merge($d,['status'=>'active','created_at'=>now(),'updated_at'=>now()]));return back()->with('success','Индивидуальный план обновлён.');}
}